import{_ as o,c as a,o as t,a2 as p}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1780541309000}'),s={name:"guide/faq.md"};function r(n,e,i,l,d,u){return t(),a("div",null,[...e[0]||(e[0]=[p('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Q: What is Gomoku?</p><p>A: Gomoku is a macOS-first board game app for five-in-a-row play. It supports human vs human, human vs AI, LAN play, and local saving of game records (<code>.sgf</code>).</p><p>Q: Which macOS versions are supported?</p><p>A: Gomoku runs on modern macOS releases; Monterey (12) and later are recommended.</p><p>Q: How do I download and install Gomoku?</p><p>A: Download the signed release from the project Releases page or install from the Mac App Store (if available). See the repository README for developer builds.</p><p>Q: How do I play over LAN?</p><p>A: Open the &quot;Online / LAN&quot; page in the app, create a room or join a visible room. Ensure Local Network permission is granted and all devices are on the same Wi‑Fi network.</p><p>Q: How do I save or export games?</p><p>A: Use the in-app Save or Export to create <code>.sgf</code> files. Choose the folder when exporting.</p><p>Q: How do I set Gomoku as the default app for <code>.sgf</code> files?</p><p>A: See the &quot;Set Gomoku as the default SGF viewer&quot; guide for Finder instructions (Get Info → Open with → Change All).</p><p>Q: Does Gomoku upload my data?</p><p>A: Gomoku is offline-first and does not upload personal data by default. LAN play transmits game data only to peers on your local network. See the Privacy Policy for details.</p><p>Q: How do I update the app?</p><p>A: Download the latest release or update through the Mac App Store (if you installed via the App Store).</p><p>Q: How do I report bugs or request features?</p><p>A: Open an issue in the project repository and include your macOS version, Gomoku version, reproduction steps, and logs if available.</p><p>Q: Where are logs and saved games stored?</p><p>A: For sandboxed (App Store) builds:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.gomoku/Data/Library/Application Support/com.w3cub.gomoku/</span></span></code></pre></div><p>Development builds may log to the console or <code>src-tauri</code> directory.</p><p>Q: Can I play against an AI?</p><p>A: Yes. Gomoku includes an AI opponent with multiple difficulty levels available in the game setup.</p><p>If you need more answers, please open an issue in the repository or consult the full documentation.</p>',26)])])}const h=o(s,[["render",r]]);export{m as __pageData,h as default};
